# R/utils_cc_catalog.R
# The pattern catalogue of the "T Records C.C" tab: every one of the 141 rows of the Claude Pattern Matrix
# (claude/U3_Claude_Pattern_Matrix.md), each with the numeric rule the R engine (utils_cc_patterns.R) applies.
# ATR = Wilder ATR(14) of the candles shown. "Prior trend" = close change over the 10 candles before the pattern,
# in ATR (down <= -1, up >= +1). Pivots = zig-zag swing points that reversed by at least 1.5 ATR.
# Columns:
#   step, key, label, bias (bullish / bearish / trend), group
#   family  : one setup counts once per family in the bias tally (avoids the five squeeze rows voting five times)
#   regime  : "trend" = shown as in-regime when ADX >= the trend threshold; "range" = when ADX <= the range threshold;
#             "any" = always
#   recency : how many of the last candles the signal may sit in to count as "now" (3 for candles, 10 for structures)
#   kind    : candle / structure / indicator / state / strategy. "state" rows have no structure: their stop and target
#             are the ATR template (stop 1.5 ATR, target 2 x risk) and they are labelled so
#   rule    : the rule as coded (shown in the tab)

cc_catalog <- local({
  r <- function(step, key, label, bias, group, family, regime, recency, kind, rule)
    data.frame(step = step, key = key, label = label, bias = bias, group = group, family = family, regime = regime,
               recency = recency, kind = kind, rule = rule, stringsAsFactors = FALSE)
  rbind(
  # ---------------------------------------------------------------- STEP 1: trend & market structure
  r(1, "dow_up", "Uptrend (Dow Theory)", "bullish", "Trend", "trend_dow", "any", 10, "structure", "Last two pivot highs higher AND last two pivot lows higher. 'Early' when the lows rise but no new higher high yet. Stop: below the last pivot low. Target: last high + the last up-leg."),
  r(1, "dow_down", "Downtrend (Dow Theory)", "bearish", "Trend", "trend_dow", "any", 10, "structure", "Last two pivot highs lower AND last two pivot lows lower. Stop: above the last pivot high. Target: last low - the last down-leg."),
  r(1, "support", "Support level", "bullish", "Support & resistance", "level_bounce", "range", 10, "structure", "3+ separate pivot lows within 0.5 ATR of each other, no close more than 0.3 ATR below the level since the first touch, price above it and within 3 ATR now. Stop: level - 0.5 ATR. Target: nearest resistance above, else 2 x risk."),
  r(1, "resistance", "Resistance level", "bearish", "Support & resistance", "level_bounce", "range", 10, "structure", "Mirror of support with pivot highs."),
  r(1, "sup_to_res", "Old support now resistance", "bearish", "Support & resistance", "role_reversal", "any", 10, "structure", "2+ pivot lows at a level, a close 0.3 ATR below it (break), then a pivot high back within 0.5 ATR of it in the last 10 candles; price below now. Stop: level + 0.5 ATR. Target: 2 x risk or nearest support."),
  r(1, "res_to_sup", "Old resistance now support", "bullish", "Support & resistance", "role_reversal", "any", 10, "structure", "Mirror: broken resistance retested from above and holding."),
  r(1, "uptrend_line", "Uptrend line", "bullish", "Trend lines", "trendline", "trend", 10, "structure", "Line through rising pivot lows with 3+ touches (within 0.35 ATR), slope at most 0.6 ATR per candle, no close more than 0.35 ATR below it; it reaches the last candle with price above it. Stop: line - 0.5 ATR. Target: last pivot high or 2 x risk."),
  r(1, "downtrend_line", "Downtrend line", "bearish", "Trend lines", "trendline", "trend", 10, "structure", "Mirror through falling pivot highs."),
  r(1, "broken_uptrend", "Broken uptrend line", "bearish", "Trend lines", "trendline_break", "any", 5, "structure", "A valid uptrend line (3+ touches) closed through by 0.2 ATR within the last 5 candles and still below. Stop: back above the line + 0.3 ATR. Target: last pivot low below."),
  r(1, "broken_downtrend", "Broken downtrend line", "bullish", "Trend lines", "trendline_break", "any", 5, "structure", "Mirror."),
  r(1, "ctr_break_up", "Broken countertrend line (uptrend continues)", "bullish", "Trend lines", "trendline_break", "trend", 5, "structure", "Main trend up (EMA50 rising, price above EMA200 when available); a falling line through 2+ pullback pivot highs in the last 40 candles is closed through upward in the last 5 candles. Stop: pullback low - 0.2 ATR. Target: prior high, else 2 x risk."),
  r(1, "ctr_break_down", "Broken countertrend line (downtrend continues)", "bearish", "Trend lines", "trendline_break", "trend", 5, "structure", "Mirror."),
  r(1, "bull_channel", "Bullish (ascending) channel", "bullish", "Channels", "channel", "trend", 10, "structure", "Valid uptrend line (3+ touches) plus a parallel line through 3+ pivot highs (within 0.5 ATR); price inside now. Stop: lower line - 0.5 ATR. Target: upper line."),
  r(1, "bear_channel", "Bearish (descending) channel", "bearish", "Channels", "channel", "trend", 10, "structure", "Mirror."),
  r(1, "bull_engulfing", "Bullish Engulfing", "bullish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Prior trend down; candle 1 down, candle 2 up with open <= candle 1 close and close >= candle 1 open, bigger body. Stop: pattern low - 0.1 ATR. Target: nearest resistance, else 2 x risk."),
  r(1, "bear_engulfing", "Bearish Engulfing", "bearish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Mirror after an up move."),
  r(1, "piercing", "Piercing Pattern", "bullish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Prior trend down; candle 1 down with body >= 0.6 ATR; candle 2 up, opens at or below candle 1 close (a 24-hour market rarely gaps below the low), closes above candle 1's body midpoint but below its open."),
  r(1, "dark_cloud", "Dark Cloud Cover", "bearish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Mirror after an up move."),
  r(1, "bull_harami", "Bullish Harami", "bullish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Prior trend down; candle 1 down with body >= 0.6 ATR; candle 2 up with body <= half of candle 1's, inside candle 1's body."),
  r(1, "bear_harami", "Bearish Harami", "bearish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Mirror after an up move."),
