  r(1, "morning_star", "Morning Star", "bullish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Prior trend down; candle 1 down body >= 0.6 ATR; candle 2 body <= 30% of candle 1's, sitting at or below candle 1's close; candle 3 up, closing above candle 1's body midpoint."),
  r(1, "evening_star", "Evening Star", "bearish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Mirror after an up move."),
  r(1, "three_white_soldiers", "Three White Soldiers", "bullish", "Candles (2-3)", "candle_run", "any", 3, "candle", "Not after an up move of more than 1 ATR; 3 up candles, bodies >= 0.5 ATR, each opening inside the prior body and closing higher, upper wick <= 30% of range."),
  r(1, "three_black_crows", "Three Black Crows", "bearish", "Candles (2-3)", "candle_run", "any", 3, "candle", "Mirror."),
  r(1, "tweezer_top", "Tweezer Top", "bearish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Prior trend up; up candle then down candle with highs within 0.1 ATR, at the highest high of the last 10 candles."),
  r(1, "tweezer_bottom", "Tweezer Bottom", "bullish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Mirror at the lowest low of the last 10 candles."),
