  r(1, "three_inside_up", "Three Inside Up", "bullish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "A bullish harami (candles 1-2) and candle 3 closing above candle 1's open."),
  r(1, "three_inside_down", "Three Inside Down", "bearish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Mirror."),
