  r(1, "three_outside_down", "Three Outside Down", "bearish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Mirror."),
  r(1, "bull_kicker", "Bullish Kicker", "bullish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Candle 1 down; candle 2 up, body >= 0.5 ATR, opening at or above candle 1's open with its low not below candle 1's open (no overlap)."),
  r(1, "bear_kicker", "Bearish Kicker", "bearish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Mirror."),
  r(1, "stick_sandwich", "Stick Sandwich", "bullish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Prior trend down; down, up, down candles with the two down closes within 0.1 ATR."),
  r(1, "matching_low", "Matching Low", "bullish", "Candles (2-3)", "candle_rev", "any", 3, "candle", "Prior trend down; two down candles closing within 0.05 ATR of each other."),
