  # ---------------------------------------------------------------- STEP 2: Fibonacci & classic price patterns
  r(2, "fib_retracement", "Fibonacci retracement", "trend", "Fibonacci", "fib", "trend", 10, "structure", "Last completed leg >= 3 ATR; price has pulled back to 38.2-61.8% of it and touched a level (within 0.3 ATR) in the last 5 candles without closing beyond 78.6%. Direction = the leg's. Stop: 78.6% level. Target: the leg's end."),
